<script setup>import{onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{teacherApi,formatTime}from'../../api/teacher';const route=useRoute(),paper=ref(),scores=reactive({}),comments=reactive({}),finalComment=ref(''),error=ref(''),notice=ref(''),busy=ref(false);function hydrate(p){paper.value=p;finalComment.value=p.teacherComment||'';p.answers.forEach(a=>{scores[a.answerId]=a.teacherScore??a.autoScore??0;comments[a.answerId]=a.teacherComment||''})}onMounted(async()=>{try{hydrate((await teacherApi.gradingPaper(route.params.submissionId)).data)}catch(e){error.value=e.message}});async function review(a){error.value='';try{hydrate((await teacherApi.reviewAnswer(a.answerId,{teacherScore:scores[a.answerId],teacherComment:comments[a.answerId]})).data);notice.value='评分已保存并重新汇总总分'}catch(e){error.value=e.message}}async function aiGrade(a){busy.value=true;try{hydrate((await teacherApi.aiGrade(a.answerId)).data)}catch(e){error.value=e.message}finally{busy.value=false}}async function saveComment(){try{hydrate((await teacherApi.saveFinalComment(paper.value.id,finalComment.value)).data);notice.value='最终评语已保存'}catch(e){error.value=e.message}}async function publish(){if(!confirm('发布后学生将立即看到成绩，确认发布吗？'))return;try{hydrate((await teacherApi.publishScore(paper.value.id)).data);notice.value='成绩已发布'}catch(e){error.value=e.message}}</script>
<template><p><RouterLink v-if="paper" :to="'/teacher/grading/exams/'+paper.examId">← 返回答卷列表</RouterLink></p><header v-if="paper" class="page-heading"><div><p class="eyebrow">REVIEW PAPER</p><h1>{{paper.studentName}} · {{paper.examTitle}}</h1><p class="muted">交卷 {{formatTime(paper.submitTime)}} · 当前总分 {{paper.totalScore}}</p></div><span class="badge">{{paper.scorePublished?'成绩已发布':paper.status}}</span></header><p v-if="error" class="error-message">{{error}}</p><p v-if="notice" class="success-message">{{notice}}</p><article v-for="(a,index) in paper?.answers" :key="a.answerId" class="surface question-card"><div class="section-head"><h2>第 {{index+1}} 题 <span class="muted">{{a.questionType==='SINGLE_CHOICE'?'单选题':'简答题'}} · 满分 {{a.maxScore}}</span></h2><span class="badge">{{a.gradingStatus}}</span></div><p class="preserve">{{a.content}}</p><div class="review-grid"><div><h3>学生答案</h3><p class="answer-preview preserve">{{a.answerContent||'（未作答）'}}</p></div><div><h3>评分参考</h3><p class="preserve">{{a.referenceAnswer}}</p><ul><li v-for="p in a.scoringPoints" :key="p.id">{{p.pointContent}}（{{p.pointScore}} 分）</li></ul><p v-if="a.autoScore!==null">系统自动分：{{a.autoScore}}</p></div></div><section v-if="a.questionType==='SHORT_ANSWER'" class="ai-panel"><div class="section-head"><h3>AI 阅卷建议</h3><button class="secondary" :disabled="busy" @click="aiGrade(a)">生成 / 重试 AI 建议</button></div><p v-if="!a.aiSuggestion" class="muted">尚未请求 AI 建议。</p><template v-else><p v-if="a.aiSuggestion.errorMessage" class="error-message">{{a.aiSuggestion.errorMessage}}</p><template v-else><p>建议分：{{a.aiSuggestion.aiScore}}</p><p>{{a.aiSuggestion.aiReason}}</p><p>{{a.aiSuggestion.aiComment}}</p><p>命中：{{a.aiSuggestion.matchedPoints.join('、')||'无'}}</p><p>缺失：{{a.aiSuggestion.missingPoints.join('、')||'无'}}</p></template></template></section><div class="form-grid"><label>教师评分（0～{{a.maxScore}}）<input v-model.number="scores[a.answerId]" type="number" min="0" :max="a.maxScore" step="0.01"></label><label>题目评语<textarea v-model="comments[a.answerId]" rows="3"></textarea></label></div><button class="primary" @click="review(a)">保存本题复核</button></article><section v-if="paper" class="surface final-review"><h2>最终评语与发布</h2><textarea v-model="finalComment" rows="4" placeholder="学生发布后可见的教师最终评语"></textarea><div class="actions"><button class="secondary" @click="saveComment">保存最终评语</button><button class="primary" :disabled="paper.scorePublished" @click="publish">{{paper.scorePublished?'已发布':'发布成绩'}}</button></div><p class="muted">所有简答题完成教师复核后才允许发布；总分优先采用教师评分，未人工改分的单选题采用自动评分。</p></section></template>
